// =============================================================================
// main_single.cpp - Smart University Examination Timetable Generator
// Single-file version for submission. GENERATED by tools/make_single.sh from
// include/ and src/ - edit those files, then run `make single`.
//
// Build: g++ -std=c++17 -Wall -Wextra -O2 main_single.cpp -o timetable
// Run  : ./timetable          (menu)
//        ./timetable --test   (self-tests)
// =============================================================================

// ======================= include/Models.h =======================
// =============================================================================
// Models.h - plain data records used by the whole project.
//
// Smart University Examination Timetable Generator
//   Vertex = subject (exam), Edge = shared student batch, Colour = time slot.
// =============================================================================

#include <string>
#include <vector>

// One examination paper. Becomes one vertex of the conflict graph.
struct Subject {
    int id = 0;               // auto-assigned, stable across edits
    std::string code;         // unique, stored upper-case, e.g. "CS101"
    std::string name;         // human-readable title
    int studentCount = 0;     // optional; 0 = derive from batches
};

// A group of students who all sit the same set of exams.
// Every pair of subjects inside one batch is a conflict edge.
struct Batch {
    int id = 0;
    std::string name;             // unique, e.g. "CSE Year 1"
    int studentCount = 0;
    std::vector<int> subjectIds;  // Subject::id values
};

// A period in which exams can be held. Only available slots are used.
struct TimeSlot {
    int id = 0;
    std::string label;        // e.g. "Day 1 - 09:00 AM"
    bool available = true;
};

// An undirected conflict between two subjects (vertex indices u < v).
struct ConflictEdge {
    int u = 0;
    int v = 0;
    int weight = 0;                    // total students shared by u and v
    std::vector<std::string> reasons;  // batch names that cause the conflict
};

// ======================= include/Graph.h =======================
// =============================================================================
// Graph.h - undirected conflict graph between subjects.
//
// Two representations are kept in sync:
//   * adjacency list   vector<vector<int>>  - O(V + E) space, fast neighbour scans
//   * adjacency matrix vector<vector<bool>> - O(V^2) space, O(1) hasEdge(), used
//                                             by backtracking and branch & bound
// Vertex i always corresponds to the i-th subject in the scheduler's list.
// =============================================================================


#include <cstddef>
#include <map>
#include <string>
#include <utility>
#include <vector>

class Graph {
public:
    Graph() = default;
    explicit Graph(int vertexCount);

    // Appends an isolated vertex and returns its index. O(V) (matrix row/col).
    int addVertex();

    // Adds (or merges into) the edge {u, v}. A repeated edge accumulates its
    // weight and records the extra reason. Self-loops / bad indices are ignored.
    void addEdge(int u, int v, int weight = 0, const std::string& reason = "");

    bool hasEdge(int u, int v) const;                 // O(1)
    int degree(int v) const;                          // O(1)
    const std::vector<int>& neighbors(int v) const;   // O(1)

    int vertexCount() const;
    int edgeCount() const;
    const std::vector<ConflictEdge>& edges() const;

    void clear();

    // Rebuilds the whole graph from scratch: one vertex per subject and, for
    // every batch, an edge between every pair of its subjects.
    // Time: O(V^2 + sum over batches of s_b^2 * log E), Space: O(V^2 + E).
    void rebuildFromBatches(const std::vector<Subject>& subjects,
                            const std::vector<Batch>& batches);

    double density() const;          // 2E / (V(V-1)), 0 when V < 2
    int maxDegree() const;
    double avgDegree() const;        // 2E / V
    int connectedComponents() const; // BFS, O(V + E)

private:
    bool validVertex(int v) const;

    std::vector<std::vector<int>> adj_;
    std::vector<std::vector<bool>> matrix_;
    std::vector<ConflictEdge> edges_;
    std::map<std::pair<int, int>, std::size_t> edgeLookup_;  // (min,max) -> edges_ index
};

// ======================= include/Coloring.h =======================
// =============================================================================
// Coloring.h - shared colouring types, the verifier, input-order greedy
// colouring, the greedy clique lower bound and the shared search order.
//
// Colour c (0-based) means "the (c+1)-th available time slot".
// =============================================================================


#include <chrono>
#include <string>
#include <utility>
#include <vector>

inline constexpr int kUncolored = -1;
inline constexpr long long kDefaultNodeLimit = 5'000'000;
inline constexpr double kDefaultTimeLimitMs = 5000.0;

// Safety limits for the exponential searches (backtracking, branch & bound).
struct SearchLimits {
    long long nodeLimit = kDefaultNodeLimit;
    double timeLimitMs = kDefaultTimeLimitMs;
};

// Everything an algorithm reports back to the user.
struct ColoringResult {
    std::string method;             // e.g. "Greedy - Input order"
    std::vector<int> colors;        // colour per vertex, kUncolored if none
    int slotsUsed = 0;
    double timeMs = 0.0;
    long long nodesExplored = 0;    // search algorithms only
    long long nodesPruned = 0;      // branch & bound only
    long long backtracks = 0;       // backtracking only
    bool success = true;            // false: backtracking found no k-colouring
    bool provenOptimal = false;     // true only when B&B finished (or UB == LB)
    bool cutOff = false;            // a safety limit stopped the search
    int lowerBound = 0;             // clique bound (B&B)
    int upperBound = 0;             // initial greedy bound (B&B)
};

// Result of validateColoring(): empty lists mean conflict-free.
struct ValidationReport {
    bool valid = true;
    std::vector<int> uncolored;                 // vertices with no slot
    std::vector<std::pair<int, int>> clashes;   // edges whose ends share a slot
};

// Small RAII timer: starts on construction.
class Stopwatch {
public:
    Stopwatch() : start_(std::chrono::steady_clock::now()) {}
    void restart() { start_ = std::chrono::steady_clock::now(); }
    double elapsedMs() const {
        const auto now = std::chrono::steady_clock::now();
        return std::chrono::duration<double, std::milli>(now - start_).count();
    }

private:
    std::chrono::steady_clock::time_point start_;
};

// Number of slots a colouring uses (largest colour + 1). O(V).
int countColors(const std::vector<int>& colors);

// -----------------------------------------------------------------------------
// validateColoring
//   Purpose : prove a timetable is conflict-free.
//   Input   : graph, colour per vertex.
//   Output  : report listing uncoloured vertices and clashing edges.
//   Time    : O(V + E)      Space: O(V) for the report in the worst case
// -----------------------------------------------------------------------------
ValidationReport validateColoring(const Graph& graph, const std::vector<int>& colors);

// -----------------------------------------------------------------------------
// greedyColorInOrder
//   Purpose : visit vertices in the given order and give each the smallest
//             colour not used by an already-coloured neighbour.
//   Input   : graph, permutation of the vertices.
//   Output  : colour per vertex (compact: 0..k-1).
//   Time    : O(V + E) - each adjacency list is scanned once.
//   Space   : O(V)
// -----------------------------------------------------------------------------
std::vector<int> greedyColorInOrder(const Graph& graph, const std::vector<int>& order);

// Vertices sorted by descending degree, ties by index. Used to seed the
// clique search. Time O(V log V), Space O(V).
std::vector<int> degreeOrder(const Graph& graph);

// Plain greedy colouring in input order (subject 0, 1, 2, ...), timed and
// packed into a ColoringResult. Fast, but not always optimal.
ColoringResult greedyColoring(const Graph& graph);

// -----------------------------------------------------------------------------
// greedyClique
//   Purpose : find a large clique quickly. A clique of size c forces c colours,
//             so its size is a valid lower bound on the chromatic number.
//   Method  : from every start vertex, add neighbours (highest degree first)
//             that are adjacent to everything chosen so far; keep the largest.
//   Time    : O(V^3) worst case    Space: O(V)
// -----------------------------------------------------------------------------
std::vector<int> greedyClique(const Graph& graph);

// Renames the colours of `target` so they overlap `reference` as much as
// possible (greedy max-overlap matching). Used by the comparison screen so
// "moved subjects" are meaningful. The result still uses colours 0..k-1.
// Time O(V + k^3), Space O(k^2).
std::vector<int> alignColors(const std::vector<int>& reference, const std::vector<int>& target);

// -----------------------------------------------------------------------------
// constrainedFirstOrder
//   Purpose : static visiting order for the exact searches (backtracking and
//             branch and bound): a greedy clique first (those vertices are
//             forced onto distinct colours anyway), then the remaining vertices
//             by descending degree, so tightly constrained subjects come early
//             and failures happen near the root of the search tree.
//   Time    : O(V^3) (dominated by greedyClique)    Space: O(V)
// -----------------------------------------------------------------------------
std::vector<int> constrainedFirstOrder(const Graph& graph);

// ======================= include/Backtracking.h =======================
// =============================================================================
// Backtracking.h - m-colouring decision problem: "can the exams fit in k slots?"
//
// Idea: colour vertices one at a time (clique first, then by descending
// degree, so tightly constrained subjects come first). For each vertex try colours 0..k-1; keep the first
// colour that is safe (no adjacent subject already has it) and recurse. If
// no colour works, undo and return to the previous vertex (backtrack).
//
// Time : O(k^V) worst case - every vertex may try every colour.
// Space: O(V) for the colour array + O(V) recursion depth (+ O(V^2) matrix).
//
// Why pruning helps in practice: isSafe() rejects a colour as soon as one
// neighbour clashes, so a whole subtree of k^(remaining) assignments is
// discarded in O(V) time. Colouring highly constrained vertices first makes
// those failures happen near the root, where each cut removes the most work.
// =============================================================================


#include <cstddef>
#include <vector>

class BacktrackingColorer {
public:
    explicit BacktrackingColorer(const Graph& graph, SearchLimits limits = SearchLimits{});

    // -------------------------------------------------------------------------
    // canColor
    //   Purpose : decide whether the graph can be coloured with at most k colours.
    //   Input   : k >= 0.
    //   Output  : ColoringResult; success == true and colors filled if possible.
    //             If a limit is hit first, cutOff == true and success == false
    //             means "unknown", not "impossible".
    //   Time    : O(k^V) worst case    Space: O(V)
    // -------------------------------------------------------------------------
    ColoringResult canColor(int k);

private:
    bool solve(std::size_t position);
    bool isSafe(std::size_t position, int color) const;  // O(V) via the matrix
    bool limitReached();

    const Graph& graph_;
    SearchLimits limits_;
    int k_ = 0;
    std::vector<int> order_;
    std::vector<int> colors_;
    long long nodes_ = 0;
    long long backtracks_ = 0;
    bool cutOff_ = false;
    Stopwatch clock_;
};

// ======================= include/BranchAndBound.h =======================
// =============================================================================
// BranchAndBound.h - minimum number of slots (chromatic number).
//
// Bounds
//   UB (upper bound) = the input-order greedy colouring - a real timetable.
//   LB (lower bound) = size of a greedily found clique - any clique of size c
//                      needs c distinct slots. If UB == LB we are done.
// Branching
//   Vertices are coloured in a fixed order (clique first, then descending degree).
//   colorsUsed = number of distinct colours in the partial colouring.
// Pruning
//   (1) Bound      : colorsUsed >= best  -> this branch cannot improve, cut.
//   (2) Symmetry   : a vertex may take an existing colour or exactly one new
//                    colour (index colorsUsed); colourings that only rename
//                    colours are never explored twice.
//   (3) Forward    : after a choice, every uncoloured neighbour must still have
//       checking     a free colour below best - 1; otherwise cut immediately.
//
// Time : O(best^V) worst case (NP-hard), usually far less thanks to pruning.
// Space: O(V * UB) neighbour-colour counters + O(V) recursion depth.
// =============================================================================


#include <cstddef>
#include <vector>

class BranchAndBoundColorer {
public:
    explicit BranchAndBoundColorer(const Graph& graph, SearchLimits limits = SearchLimits{});

    // -------------------------------------------------------------------------
    // solve
    //   Purpose : find a colouring with the fewest colours.
    //   Input   : the graph given to the constructor.
    //   Output  : best colouring found; provenOptimal == true unless a safety
    //             limit cut the search off (then cutOff == true).
    //   Time    : exponential worst case    Space: O(V * UB)
    // -------------------------------------------------------------------------
    ColoringResult solve();

private:
    void search(std::size_t position, int colorsUsed);
    void assign(int vertex, int color);
    void unassign(int vertex, int color);
    bool forwardCheck(int vertex, int colorLimit) const;
    bool limitReached();
    std::vector<int> buildOrder(const std::vector<int>& clique) const;

    const Graph& graph_;
    SearchLimits limits_;
    std::vector<int> order_;
    std::vector<int> colors_;
    // conflictCount_[v][c] = how many neighbours of v currently have colour c.
    std::vector<std::vector<int>> conflictCount_;
    std::vector<int> bestColors_;
    int best_ = 0;
    int lowerBound_ = 0;
    long long nodes_ = 0;
    long long pruned_ = 0;
    bool cutOff_ = false;
    bool stop_ = false;
    Stopwatch clock_;
};

// ======================= include/Scheduler.h =======================
// =============================================================================
// Scheduler.h - owns all data (subjects, batches, slots), keeps the conflict
// graph in sync, maps colours to real time slots and handles file I/O.
// =============================================================================


#include <optional>
#include <string>
#include <vector>

// A colouring translated into real, available time slots.
struct Schedule {
    std::vector<int> colors;           // colour per subject index (input)
    int slotsNeeded = 0;               // colours used
    int slotsAvailable = 0;
    bool feasible = false;             // slotsNeeded <= slotsAvailable
    std::vector<TimeSlot> slotForColor;   // colour c -> c-th available slot
    // Partial timetable when infeasible: colour per subject, kUncolored if
    // the subject could not be placed in any available slot.
    std::vector<int> partialColors;
    std::vector<int> outsideSlots;     // subjects whose colour had no slot
    std::vector<int> unplaced;         // still unplaced after re-fitting
};

class ExamScheduler {
public:
    // --- subjects ------------------------------------------------------------
    bool addSubject(const std::string& code, const std::string& name, int students,
                    std::string& error);
    bool removeSubject(int id, std::string& error);  // also updates batches

    // --- batches -------------------------------------------------------------
    bool addBatch(const std::string& name, int students, const std::vector<int>& subjectIds,
                  std::string& error);
    bool removeBatch(int id, std::string& error);

    // --- slots ---------------------------------------------------------------
    bool addSlot(const std::string& label, std::string& error);
    bool removeSlot(int id, std::string& error);
    bool setSlotAvailable(int id, bool available, std::string& error);

    void clear();

    // --- queries -------------------------------------------------------------
    const std::vector<Subject>& subjects() const { return subjects_; }
    const std::vector<Batch>& batches() const { return batches_; }
    const std::vector<TimeSlot>& slots() const { return slots_; }
    const Graph& graph() const { return graph_; }
    bool empty() const { return subjects_.empty() && batches_.empty() && slots_.empty(); }

    int subjectIndexById(int id) const;                     // -1 if unknown
    int subjectIndexByCode(const std::string& code) const;  // case-insensitive
    std::vector<TimeSlot> availableSlots() const;
    int studentsForSubject(int index) const;  // explicit count or batch sum
    int totalStudents() const;                // sum over batches
    std::string batchNamesForSubject(int index) const;

    // Maps colours to available slots; builds a partial timetable if short.
    Schedule makeSchedule(const std::vector<int>& colors) const;

    // The last generated timetable (cleared when subjects/batches change).
    void recordResult(const ColoringResult& result) { lastResult_ = result; }
    const std::optional<ColoringResult>& lastResult() const { return lastResult_; }

    // --- persistence (pipe-separated text, see README) -----------------------
    bool saveToFile(const std::string& path, std::string& error) const;
    bool loadFromFile(const std::string& path, std::string& error);

    // Validation helpers shared with the UI.
    static std::string trim(const std::string& text);
    static std::string toUpper(std::string text);
    static bool validText(const std::string& text, const std::string& what, std::string& error);

private:
    bool insertSubject(const Subject& subject, std::string& error);
    bool insertBatch(const Batch& batch, std::string& error);
    bool insertSlot(const TimeSlot& slot, std::string& error);
    int batchIndexById(int id) const;
    int slotIndexById(int id) const;
    void rebuildGraph();

    std::vector<Subject> subjects_;
    std::vector<Batch> batches_;
    std::vector<TimeSlot> slots_;
    Graph graph_;
    std::optional<ColoringResult> lastResult_;
    int nextSubjectId_ = 1;
    int nextBatchId_ = 1;
    int nextSlotId_ = 1;
};

